import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './CardHeading.module.css'

export interface CardHeadingProps extends Omit<ComponentProps<'div'>, 'title'> {
  title: ReactNode
  description?: ReactNode
  media?: ReactNode
  actions?: ReactNode
  headingLevel?: 2 | 3 | 4
}

/**
 * The top row of a card: what it is, and what you can do with it. Put it
 * first inside a Card; the card's padding and gap space it.
 */
export function CardHeading({
  title,
  description,
  media,
  actions,
  headingLevel = 2,
  className,
  ...props
}: CardHeadingProps) {
  const Heading = `h${headingLevel}` as const
  return (
    <div className={cn(styles.cardHeading, className)} {...props}>
      <div className={styles.lead}>
        {media && (
          <span className={styles.media} aria-hidden="true">
            {media}
          </span>
        )}
        <div className={styles.text}>
          <Heading className={styles.title}>{title}</Heading>
          {description && <p className={styles.description}>{description}</p>}
        </div>
      </div>
      {actions && <div className={styles.actions}>{actions}</div>}
    </div>
  )
}

/* Title and actions share a row while there is room; the actions drop
   under the title when there is not, rather than squeezing it. */
.cardHeading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-cluster) var(--space-group);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
}

.lead {
  display: flex;
  align-items: center;
  gap: var(--space-cluster);
  flex: 1 1 16rem;
  min-inline-size: 0;
}

.media {
  display: inline-flex;
  flex-shrink: 0;
  font-size: var(--icon-md);
  color: var(--muted-foreground);
}

.text {
  display: grid;
  gap: var(--space-1);
  min-inline-size: 0;
}

.title {
  margin: 0;
  font-size: var(--text-heading-sm);
  line-height: var(--leading-heading-sm);
  font-weight: 600;
  overflow-wrap: anywhere;
}

.description {
  margin: 0;
  color: var(--muted-foreground);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-inline);
}
